import{_ as n,a0 as r,w as p,s as o,ao as d,I as e,x as s,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 上使用 tarball | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 tarball | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 tarball | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 tarball | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181217 Working with tarballs on Linux","title":"在 Linux 上使用 tarball","tag":"201901","desc":""},"relativePath":"201901/20181217 Working with tarballs on Linux.md","filePath":"[post].md"}'),h={name:"201901/20181217 Working with tarballs on Linux.md"};function g(b,a,k,u,c,f){const t=r("Link");return p(),o("div",null,[a[15]||(a[15]=d(`<h1 id="在-linux-上使用-tarball" tabindex="-1">在 Linux 上使用 tarball <a class="header-anchor" href="#在-linux-上使用-tarball" aria-label="Permalink to “在 Linux 上使用 tarball”">​</a></h1><blockquote><p>Tarball 提供了一種在 Linux 系統上備份和管理一組文件的通用方法。請按照以下提示瞭解如何創建它們，以及從中提取和刪除單個文件。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/12/tarball-100783148-large.jpg" alt=""></p><p>“tarball” （LCTT 譯註：國內也常稱為“tar 包”）一詞通常用於描述備份一組選擇的文件並將它們打包在一個文件中的一種文件格式。該名稱來自 .tar 文件擴展名和 <code>tar</code> 命令，它用於將文件打包到一個文件中，有時還會壓縮該文件，使其在移動到其它系統時更小。</p><p>tarball 通常用於備份個人或系統文件來創建存檔，特別是在進行可能需要撤消的更改之前。例如，Linux 系統管理員通常會在更改應用之前創建包含一系列配置文件的 tarball，以防必須撤消這些更改。從 tarball 中解壓文件通常比在備份中搜索文件快。</p><h3 id="如何在-linux-上創建-tarball" tabindex="-1">如何在 Linux 上創建 tarball <a class="header-anchor" href="#如何在-linux-上創建-tarball" aria-label="Permalink to “如何在 Linux 上創建 tarball”">​</a></h3><p>使用如下命令，你可以在單條命令中創建 tarball 並壓縮它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -cvzf PDFs.tar.gz *.pdf</span></span></code></pre></div><p>其結果是一個壓縮文件（gzip 壓縮的），其中包含了當前目錄中的所有 PDF 文件。當然，壓縮是可選的。一個稍微簡單的只是將 PDF 文件打包成未壓縮 tarball 的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -cvf PDFs.tar *.pdf</span></span></code></pre></div><p>注意，選項中的 <code>z</code> 將文件變成壓縮的。 <code>c</code> 表明創建文件，<code>v</code>（詳細）表示你在命令運行時需要一些反饋。如果你不想查看列出的文件，請忽略 <code>v</code>。</p><p>另一個常見的命名約定是給壓縮的 tarball 命名成 .tgz 而不是雙擴展名 .tar.gz，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar cvzf MyPDFs.tgz *.pdf</span></span></code></pre></div><h3 id="如何從-tarball-中解壓文件" tabindex="-1">如何從 tarball 中解壓文件 <a class="header-anchor" href="#如何從-tarball-中解壓文件" aria-label="Permalink to “如何從 tarball 中解壓文件”">​</a></h3><p>要從 gzip 壓縮包中解壓所有文件，你可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf file.tar.gz</span></span></code></pre></div><p>如果使用 .tgz 命名約定，該命令將如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf MyPDFs.tgz</span></span></code></pre></div><p>要從 gzip 包中解壓單個文件，你可以執行幾乎相同的操作，只需添加文件名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -xvzf PDFs.tar.gz ShenTix.pdf</span></span>
<span class="line"><span>ShenTix.pdf</span></span>
<span class="line"><span>ls -l ShenTix.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 122057 Dec 14 14:43 ShenTix.pdf</span></span></code></pre></div><p>如果未壓縮 tarball，你甚至可以從 tarball 中刪除文件。例如，如果我們想從 PDFs.tar.gz 中刪除我們上面解壓過的文件，我們會這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gunzip PDFs.tar.gz</span></span>
<span class="line"><span>$ ls -l PDFs.tar</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10700800 Dec 15 11:51 PDFs.tar</span></span>
<span class="line"><span>$ tar -vf PDFs.tar --delete ShenTix.pdf</span></span>
<span class="line"><span>$ ls -l PDFs.tar</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10577920 Dec 15 11:45 PDFs.tar</span></span></code></pre></div><p>請注意，我們在刪除 ShenTix.pdf 後，縮小了一點 tarball 文件佔用的空間。如果我們想要，我們可以再次壓縮文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gzip -f PDFs.tar</span></span>
<span class="line"><span>ls -l PDFs.tar.gz</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs 10134499 Dec 15 11:51 PDFs.tar.gzFlickr / James St. John</span></span></code></pre></div><p>豐富的命令列選項使得 tarball 使用起來簡單方便。</p><hr>`,26)),e("p",null,[a[1]||(a[1]=s("via: ",-1)),i(t,{href:"https://www.networkworld.com/article/3328840/linux/working-with-tarballs-on-linux.html"},{default:l(()=>[...a[0]||(a[0]=[s("https://www.networkworld.com/article/3328840/linux/working-with-tarballs-on-linux.html",-1)])]),_:1})]),e("p",null,[a[6]||(a[6]=s("作者：",-1)),i(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:l(()=>[...a[2]||(a[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),a[7]||(a[7]=s(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...a[3]||(a[3]=[s("lujun9972",-1)])]),_:1}),a[8]||(a[8]=s(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:l(()=>[...a[4]||(a[4]=[s("geekpi",-1)])]),_:1}),a[9]||(a[9]=s(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:l(()=>[...a[5]||(a[5]=[s("wxy",-1)])]),_:1})]),e("p",null,[a[12]||(a[12]=s("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...a[10]||(a[10]=[s("LCTT",-1)])]),_:1}),a[13]||(a[13]=s(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:l(()=>[...a[11]||(a[11]=[s("Linux中國",-1)])]),_:1}),a[14]||(a[14]=s(" 榮譽推出",-1))])])}const C=n(h,[["render",g]]);export{w as __pageData,C as default};
